begin;

alter table public.arena_challenges
  add column if not exists challenge_type text not null default 'Logic Error',
  add column if not exists expected_behavior text not null default '';

alter table public.arena_challenges drop constraint if exists arena_challenges_challenge_type_check;
alter table public.arena_challenges add constraint arena_challenges_challenge_type_check
  check (challenge_type in (
    'Logic Error', 'Runtime Error', 'Syntax Error', 'Async Bug',
    'Performance Issue', 'Data Handling', 'API Error', 'Security Fundamentals'
  ));

revoke select (solution_code, expected_behavior) on public.arena_challenges from anon, authenticated;
grant select (
  id, title, slug, description, problem_statement, category_id, technology_id, related_bug_id,
  difficulty, language, challenge_type, starter_code, explanation, estimated_minutes,
  is_published, created_at, updated_at
) on public.arena_challenges to anon, authenticated;

insert into public.arena_challenges (
  title, slug, description, problem_statement, category_id, technology_id, difficulty,
  language, challenge_type, starter_code, solution_code, expected_behavior, explanation,
  estimated_minutes, is_published
)
values
('Guard the Missing User', 'guard-missing-user-arena', 'A profile page throws while loading user data.', 'Update the profile lookup so nullish users render a loading label.', (select id from arena_categories where slug='javascript-errors'), (select id from technologies where slug='javascript'), 'beginner', 'javascript', 'Runtime Error', 'const user = undefined;\nconst name = user.profile.name;\nconsole.log(name);', 'const user = undefined;\nconst name = user?.profile?.name ?? "Loading…";\nconsole.log(name);', 'Loading… until a user profile exists.', 'Optional chaining prevents property access on nullish values.', 10, true),
('Fix the Array Mapper', 'fix-array-mapper', 'A mapped array contains transformed values instead of the requested totals.', 'Return the sum for every numeric batch.', (select id from arena_categories where slug='javascript-errors'), (select id from technologies where slug='javascript'), 'beginner', 'javascript', 'Logic Error', 'function total(values) { return values.map(v => v + 1); }\nconsole.log(total([1,2,3]));', 'function total(values) { return values.reduce((sum, v) => sum + v, 0); }\nconsole.log(total([1,2,3]));', 'An array containing [1, 2, 3] produces 6.', 'map transforms elements; reduce accumulates them into one result.', 10, true),
('Stop the Loop Early', 'stop-loop-early', 'A search loop keeps running after finding the target.', 'Stop searching as soon as the target is found.', (select id from arena_categories where slug='javascript-errors'), (select id from technologies where slug='javascript'), 'beginner', 'javascript', 'Logic Error', 'function contains(values, target) { for (let i=0; i<values.length; i++) { console.log(values[i]); } return false; }', 'function contains(values, target) { return values.includes(target); }', 'Returns true for an existing target and false otherwise.', 'includes expresses membership directly and short-circuits.', 10, true),
('Handle an Empty Queue', 'handle-empty-queue', 'Removing a queue item fails when the queue is empty.', 'Safely return null instead of reading an undefined item.', (select id from arena_categories where slug='javascript-errors'), (select id from technologies where slug='javascript'), 'beginner', 'javascript', 'Runtime Error', 'function dequeue(queue) { return queue.shift().value; }', 'function dequeue(queue) { const item = queue.shift(); return item ? item.value : null; }', 'Removing from an empty array returns null.', 'The removed value must be checked before its property is read.', 10, true),
('Repair Object Fallbacks', 'repair-object-fallbacks', 'The wrong fallback is used when a value is explicitly false or zero.', 'Use nullish defaults without replacing valid false or zero values.', (select id from arena_categories where slug='javascript-errors'), (select id from technologies where slug='javascript'), 'intermediate', 'javascript', 'Data Handling', 'const value = inputCount || 10;', 'const value = inputCount ?? 10;', 'Preserve 0 and false while defaulting null and undefined.', 'Or treats every falsy value as missing; nullish coalescing does not.', 15, true),
('Normalize Promise Rejection', 'normalize-promise-rejection', 'An asynchronous function resolves but rejects with inconsistent values.', 'Reject with an Error and handle the failure at the caller.', (select id from arena_categories where slug='javascript-errors'), (select id from technologies where slug='javascript'), 'intermediate', 'javascript', 'Async Bug', 'async function load() { throw "network failed"; }', 'async function load() { throw new Error("network failed"); }\nload().catch(error => console.error(error.message));', 'The caller receives an Error with a useful message.', 'Throw Error objects so failures retain stack and message metadata.', 20, true),
('Fix React Loading State', 'fix-react-loading-state', 'A React component reads API data before it has loaded.', 'Render a loading state until the requested data exists.', (select id from arena_categories where slug='react-debugging'), (select id from technologies where slug='react'), 'beginner', 'javascript', 'Runtime Error', 'function Profile({user}) { return <p>{user.name}</p>; }', 'function Profile({user}) { if (!user) return <p>Loading…</p>; return <p>{user.name}</p>; }', 'Loading is shown for nullish user data.', 'Guard loading data before rendering dependent fields.', 10, true),
('Sync React State Update', 'sync-react-state-update', 'A counter update relies on stale state after rapid clicks.', 'Use the functional state updater to calculate the next value.', (select id from arena_categories where slug='react-debugging'), (select id from technologies where slug='react'), 'beginner', 'javascript', 'Logic Error', 'setCount(count + 1);', 'setCount(current => current + 1);', 'Rapid state updates produce the correct final count.', 'Functional updates receive the latest queued state value.', 10, true),
('Repair Effect Dependency', 'repair-effect-dependency', 'An effect does not rerun when its external identifier changes.', 'Include every reactive dependency used by the effect.', (select id from arena_categories where slug='react-debugging'), (select id from technologies where slug='react'), 'intermediate', 'javascript', 'Logic Error', 'useEffect(() => load(userId), []);', 'useEffect(() => load(userId), [userId]);', 'Loading restarts when userId changes.', 'useEffect dependencies must describe values read by the effect.', 15, true),
('Clean Up Event Listener', 'clean-up-event-listener', 'A React effect leaks listeners after each render.', 'Return a cleanup function that removes the listener.', (select id from arena_categories where slug='react-debugging'), (select id from technologies where slug='react'), 'intermediate', 'javascript', 'Performance Issue', 'useEffect(() => window.addEventListener("resize", resize));', 'useEffect(() => { window.addEventListener("resize", resize); return () => window.removeEventListener("resize", resize); }, []);', 'Each mounted listener has one matching cleanup.', 'Removing listeners prevents duplicate handlers and memory growth.', 20, true),
('Fix Node Module Import', 'fix-node-module-import', 'A CommonJS module imports an ES module export incorrectly.', 'Import and export values consistently for the selected module format.', (select id from arena_categories where slug='nodejs-problems'), (select id from technologies where slug='nodejs'), 'beginner', 'javascript', 'Runtime Error', 'const config = require("./config");', 'const { value } = require("./config");\nmodule.exports = { value };', 'The required module exposes the expected named value.', 'CommonJS destructuring must match module.exports.', 10, true),
('Await the Database Call', 'await-database-call', 'A Node.js route returns before the database promise resolves.', 'Await the query and only then build the response.', (select id from arena_categories where slug='nodejs-problems'), (select id from technologies where slug='nodejs'), 'intermediate', 'javascript', 'Async Bug', 'async function handler(req, res) { const rows = db.query("select 1"); res.json(rows); }', 'async function handler(req, res) { const rows = await db.query("select 1"); res.json(rows); }', 'The response contains resolved query rows.', 'Await unwraps promise results before they are sent.', 15, true),
('Close the Server Resource', 'close-server-resource', 'An HTTP server resource is not closed during shutdown.', 'Close the server and wait for completion before exiting.', (select id from arena_categories where slug='nodejs-problems'), (select id from technologies where slug='nodejs'), 'advanced', 'javascript', 'Data Handling', 'process.on("SIGTERM", () => process.exit(0));', 'process.on("SIGTERM", () => { server.close(() => process.exit(0)); });', 'Shutdown closes listening connections before exit.', 'Graceful shutdown starts server close before process termination.', 25, true),
('Narrow the Unknown Value', 'narrow-unknown-value', 'A TypeScript utility calls string methods on unknown input.', 'Narrow the value before string operations.', (select id from arena_categories where slug='typescript-issues'), (select id from technologies where slug='typescript'), 'beginner', 'typescript', 'Syntax Error', 'function upper(value: unknown) { return value.toUpperCase(); }', 'function upper(value: unknown) { return typeof value === "string" ? value.toUpperCase() : ""; }', 'Strings become uppercase and non-strings become empty.', 'Runtime type narrowing is required for unknown values.', 15, true),
('Return the Correct Shape', 'return-correct-shape', 'A TypeScript API response type and runtime object disagree.', 'Return an object containing the declared fields only.', (select id from arena_categories where slug='typescript-issues'), (select id from technologies where slug='typescript'), 'intermediate', 'typescript', 'Data Handling', 'type User = { id: number; name: string }; const user = { id: 1 };', 'const user: User = { id: 1, name: "" };', 'A User value contains both required fields.', 'Declared fields also need runtime values.', 15, true),
('Await Python Data', 'await-python-data', 'The Python function mutates values instead of returning its computed total.', 'Accumulate the values and return the total.', (select id from arena_categories where slug='javascript-errors'), (select id from technologies where slug='python'), 'beginner', 'python', 'Logic Error', 'def total(values):\n    for value in values:\n        total = 0\n        total + value', 'def total(values):\n    return sum(values)', 'total([1, 2, 3]) is 6.', 'sum() accumulates each iterable value.', 10, true),
('Fix Python Indentation', 'fix-python-indentation', 'A Python conditional has inconsistent indentation.', 'Indent the return condition consistently.', (select id from arena_categories where slug='javascript-errors'), (select id from technologies where slug='python'), 'beginner', 'python', 'Syntax Error', 'def is_adult(age):\nif age >= 18:\n return True\nreturn False', 'def is_adult(age):\n    if age >= 18:\n        return True\n    return False', 'Age 18 is true and younger ages are false.', 'The conditional body belongs within the function block.', 10, true),
('Guard Null Coordinates', 'guard-null-coordinates', 'Python code reads coordinates from a nullable record.', 'Return None unless both coordinates are available.', (select id from arena_categories where slug='javascript-errors'), (select id from technologies where slug='python'), 'intermediate', 'python', 'Runtime Error', 'def latitude(record):\n    return record["location"]["latitude"]', 'def latitude(record):\n    if record is None or record.get("location") is None:\n        return None\n    return record["location"].get("latitude")', 'Null records produce None instead of an exception.', 'Check each nullable level before reading it.', 15, true),
('Avoid Mutable Default', 'avoid-mutable-default', 'A Python function appends to a list reused between calls.', 'Initialize the list inside the function.', (select id from arena_categories where slug='javascript-errors'), (select id from technologies where slug='python'), 'intermediate', 'python', 'Data Handling', 'def add_item(item, items=[]):\n    items.append(item)\n    return items', 'def add_item(item, items=None):\n    items = [] if items is None else items\n    items.append(item)\n    return items', 'Separate calls with omitted items do not share state.', 'Mutable default arguments persist for the life of the process.', 15, true),
('Repair API Response Handler', 'repair-api-response-handler', 'The API response handler reads JSON from an unsuccessful response.', 'Check response.ok before parsing and use the failure message.', (select id from arena_categories where slug='api-networking'), (select id from technologies where slug='javascript'), 'intermediate', 'javascript', 'API Error', 'async function readResponse(response) { return await response.json(); }', 'async function readResponse(response) { if (!response.ok) throw new Error("Request failed"); return await response.json(); }', 'Successful responses return JSON; failures throw.', 'HTTP status should be checked before relying on JSON content.', 15, true),
('Forward the Authorization Header', 'forward-authorization-header', 'A proxy drops an incoming authorization header.', 'Copy the header to the upstream request explicitly.', (select id from arena_categories where slug='api-networking'), (select id from technologies where slug='nodejs'), 'intermediate', 'javascript', 'Security Fundamentals', 'fetch(upstream);', 'fetch(upstream, { headers: { authorization: req.headers.authorization ?? "" } });', 'The upstream request receives the caller authorization header.', 'Proxy configuration must forward security-sensitive headers intentionally.', 20, true),
('Fix the Off-by-One Page', 'fix-off-by-one-page', 'Pagination skips the first item and repeats the last page.', 'Use half-open start/end indexes derived from page and page size.', (select id from arena_categories where slug='javascript-errors'), (select id from technologies where slug='javascript'), 'beginner', 'javascript', 'Logic Error', 'function page(items, page, size) { return items.slice(page * size, (page + 1) * size); }', 'function page(items, page, size) { return items.slice((page - 1) * size, page * size); }', 'Page 1 starts at index 0 and page 2 starts after the page size.', 'Off-by-one bugs commonly come from inconsistent zero- and one-based numbering.', 15, true),
('Correct SQL Active Users', 'correct-sql-active-users', 'A query counts users who belong to either state and duplicates joined rows.', 'Filter and aggregate without duplicated joins.', (select id from arena_categories where slug='database-problems'), (select id from technologies where slug='sql'), 'intermediate', 'sql', 'Logic Error', 'SELECT * FROM users WHERE status = ''active'' OR status = ''pending'';', 'SELECT * FROM users WHERE status IN (''active'', ''pending'');', 'The query returns only active or pending users.', 'IN expresses membership against both states without broadened row selection.', 15, true),
('Repair SQL Aggregate', 'repair-sql-aggregate', 'A grouped query does not include the grouped column.', 'Select only grouping columns and aggregate expressions.', (select id from arena_categories where slug='database-problems'), (select id from technologies where slug='sql'), 'intermediate', 'sql', 'Syntax Error', 'SELECT user_id, email, COUNT(*) FROM orders GROUP BY user_id;', 'SELECT user_id, COUNT(*) FROM orders GROUP BY user_id;', 'Each user appears once with the number of orders.', 'Every selected nonaggregate column must be part of the grouping set.', 20, true),
('Prevent Duplicate Database Writes', 'prevent-duplicate-database-writes', 'A transaction inserts duplicate records because it lacks a unique constraint.', 'Add an idempotency key and check it atomically.', (select id from arena_categories where slug='database-problems'), (select id from technologies where slug='sql'), 'advanced', 'sql', 'Data Handling', 'INSERT INTO payments (reference, amount) VALUES (''INV-1'', 100);', 'INSERT INTO payments (reference, amount) VALUES (''INV-1'', 100)\nON CONFLICT (reference) DO NOTHING;', 'Retrying the same reference creates no duplicate row.', 'Database constraints provide stronger protection than application-only checks.', 25, true),
('Resolve Flex Overflow', 'resolve-flex-overflow', 'A flex item has a minimum width larger than its container.', 'Allow the item to shrink and wrap long text.', (select id from arena_categories where slug='css-html-problems'), (select id from technologies where slug='css'), 'beginner', 'css', 'Data Handling', '.panel { min-width: 500px; }', '.panel { min-width: 0; overflow-wrap: anywhere; }', 'Long content stays within the available panel width.', 'Flex children default to a minimum content width that can overflow.', 10, true),
('Center Dialog Accessibly', 'center-dialog-accessibly', 'A dialog is visually centered but inaccessible to keyboard users.', 'Use semantic dialog markup and visible focus styles.', (select id from arena_categories where slug='css-html-problems'), (select id from technologies where slug='html'), 'intermediate', 'html', 'Data Handling', '<div>Dialog content</div>', '<dialog open aria-labelledby="dialog-title"><h2 id="dialog-title">Dialog content</h2></dialog>', 'The dialog exposes its role and accessible name.', 'Native dialog markup supplies semantics unavailable from a generic div.', 15, true),
('Repair CSS Specificity', 'repair-css-specificity', 'A lower-specificity component rule unexpectedly overrides the design token.', 'Apply the token in a single scoped rule without increasing specificity artificially.', (select id from arena_categories where slug='css-html-problems'), (select id from technologies where slug='css'), 'intermediate', 'css', 'Logic Error', '.button.primary { color: red !important; }', '.button { color: var(--button-color); }', 'The scoped button uses the intended design token.', 'Specificity and important declarations make styling behavior harder to reason about.', 15, true),
('Resolve Merge Conflict Markers', 'resolve-merge-conflict-markers', 'Merged source still contains Git conflict marker lines.', 'Remove markers and choose one consistent implementation.', (select id from arena_categories where slug='javascript-errors'), (select id from technologies where slug='git'), 'beginner', 'text', 'Syntax Error', '<<<<<<< HEAD\nconst mode = "light";\n=======\nconst mode = "dark";\n>>>>>>> feature', 'const mode = "dark";', 'The source contains no conflict markers and has one selected value.', 'Conflict markers are not valid source and must be resolved during merge.', 15, true),
('Preserve Rebasing Commits', 'preserve-rebasing-commits', 'A contributor runs a hard reset while resolving a rebase.', 'Rebase carefully and restore commits instead of deleting the working branch.', (select id from arena_categories where slug='javascript-errors'), (select id from technologies where slug='git'), 'advanced', 'text', 'Data Handling', 'git reset --hard HEAD~1', 'git rebase --continue', 'Rebase commits remain intact after conflict resolution.', 'Rebase continuation preserves commits and resolves conflicts incrementally.', 20, true),
('Remove the N Plus One Query', 'remove-n-plus-one-query', 'A list request performs one query per related record.', 'Load the related records in a single joined query.', (select id from arena_categories where slug='database-problems'), (select id from technologies where slug='database'), 'advanced', 'sql', 'Performance Issue', 'for (const user of users) { await db.query("select * from orders where user_id=$1", [user.id]); }', 'const rows = await db.query("select users.*, orders.* from users join orders on orders.user_id=users.id");', 'One request retrieves users and related rows without per-item queries.', 'Joining removes repeated round trips to the database.', 25, true),
('Stop an Async Race', 'stop-async-race', 'The slower stale request overwrites newer API results.', 'Ignore stale responses using a request identity check.', (select id from arena_categories where slug='javascript-errors'), (select id from technologies where slug='javascript'), 'expert', 'javascript', 'Async Bug', 'setResult(await fetch(`/api?q=${query}`).then(r => r.json()));', 'const requestId = ++latestRequest;\nfetch(`/api?q=${query}`).then(r => r.json()).then(result => { if (requestId === latestRequest) setResult(result); });', 'Only the most recent request updates visible results.', 'Request identities prevent stale promises from winning a race.', 30, true),
('Clean Event Listeners', 'clean-event-listeners', 'A long-running process adds listeners faster than they are removed.', 'Remove listeners when subscriptions are disposed.', (select id from arena_categories where slug='nodejs-problems'), (select id from technologies where slug='nodejs'), 'expert', 'javascript', 'Performance Issue', 'emitter.on("change", handler);', 'emitter.on("change", handler);\nfunction dispose() { emitter.off("change", handler); }', 'Every subscription has a matching removal path.', 'Unbounded listener attachment eventually exhausts process resources.', 30, true),
('Validate SQL Identifier', 'validate-sql-identifier', 'A dynamic table name enables SQL injection.', 'Use strict allowlists and parameter binding rather than raw identifiers.', (select id from arena_categories where slug='database-problems'), (select id from technologies where slug='database'), 'advanced', 'sql', 'Security Fundamentals', 'SELECT * FROM ${tableName};', 'SELECT * FROM allowed_tables WHERE name = $1;', 'User input selects a preapproved identifier through bound parameters.', 'Identifiers cannot be bound as values and require an allowlist.', 25, true)
on conflict (slug) do update set
  description=excluded.description,
  problem_statement=excluded.problem_statement,
  starter_code=excluded.starter_code,
  solution_code=excluded.solution_code,
  expected_behavior=excluded.expected_behavior,
  explanation=excluded.explanation,
  is_published=true,
  updated_at=now();

-- Keep the initial Arena collection at exactly 30 challenges.
delete from public.arena_challenges
where slug in ('stop-loop-early', 'handle-empty-queue', 'center-dialog-accessibly', 'preserve-rebasing-commits');

insert into public.arena_test_cases (challenge_id, title, stdin, expected_output, is_public, position)
select c.id, 'Required behavior', '', c.expected_behavior, true, 1
from public.arena_challenges c
where c.is_published
on conflict do nothing;

insert into public.arena_test_cases (challenge_id, title, stdin, expected_output, is_public, position)
select c.id, 'Edge case', '', c.expected_behavior, false, 2
from public.arena_challenges c
where c.is_published
on conflict do nothing;

insert into public.arena_hints (challenge_id, sequence, hint)
select c.id, 1, 'Identify the line where the current behavior first differs from the requirement.'
from public.arena_challenges c
where c.slug in ('guard-missing-user-arena','fix-array-mapper','stop-loop-early','handle-empty-queue','repair-object-fallbacks','normalize-promise-rejection','fix-react-loading-state','sync-react-state-update','repair-effect-dependency','clean-up-event-listener','fix-node-module-import','await-database-call','close-server-resource','narrow-unknown-value','return-correct-shape','await-python-data','fix-python-indentation','guard-null-coordinates','avoid-mutable-default','repair-api-response-handler','forward-authorization-header','fix-off-by-one-page','correct-sql-active-users','repair-sql-aggregate','prevent-duplicate-database-writes','resolve-flex-overflow','center-dialog-accessibly','repair-css-specificity','resolve-merge-conflict-markers','preserve-rebasing-commits','remove-n-plus-one-query','stop-async-race','clean-event-listeners','validate-sql-identifier')
on conflict (challenge_id, sequence) do update set hint=excluded.hint;

insert into public.arena_hints (challenge_id, sequence, hint)
select c.id, 2, 'Look for a built-in language or framework feature that expresses the required behavior directly.'
from public.arena_challenges c
where c.slug in ('guard-missing-user-arena','fix-array-mapper','stop-loop-early','handle-empty-queue','repair-object-fallbacks','normalize-promise-rejection','fix-react-loading-state','sync-react-state-update','repair-effect-dependency','clean-up-event-listener','fix-node-module-import','await-database-call','close-server-resource','narrow-unknown-value','return-correct-shape','await-python-data','fix-python-indentation','guard-null-coordinates','avoid-mutable-default','repair-api-response-handler','forward-authorization-header','fix-off-by-one-page','correct-sql-active-users','repair-sql-aggregate','prevent-duplicate-database-writes','resolve-flex-overflow','center-dialog-accessibly','repair-css-specificity','resolve-merge-conflict-markers','preserve-rebasing-commits','remove-n-plus-one-query','stop-async-race','clean-event-listeners','validate-sql-identifier')
on conflict (challenge_id, sequence) do update set hint=excluded.hint;

insert into public.arena_hints (challenge_id, sequence, hint)
select c.id, 3, 'After fixing the root cause, verify both the normal path and the relevant edge case.'
from public.arena_challenges c
where c.slug in ('guard-missing-user-arena','fix-array-mapper','stop-loop-early','handle-empty-queue','repair-object-fallbacks','normalize-promise-rejection','fix-react-loading-state','sync-react-state-update','repair-effect-dependency','clean-up-event-listener','fix-node-module-import','await-database-call','close-server-resource','narrow-unknown-value','return-correct-shape','await-python-data','fix-python-indentation','guard-null-coordinates','avoid-mutable-default','repair-api-response-handler','forward-authorization-header','fix-off-by-one-page','correct-sql-active-users','repair-sql-aggregate','prevent-duplicate-database-writes','resolve-flex-overflow','center-dialog-accessibly','repair-css-specificity','resolve-merge-conflict-markers','preserve-rebasing-commits','remove-n-plus-one-query','stop-async-race','clean-event-listeners','validate-sql-identifier')
on conflict (challenge_id, sequence) do update set hint=excluded.hint;

notify pgrst, 'reload schema';
commit;
